                reg_rdata[0 +: 1] = cmd_fork;
            end
            11'h600: begin
                reg_rdata[0 +: 1] = cmd_ack;
            end
            11'h601: begin
                reg_rdata[0 +: 1] = cmd_done;
            end
            default: reg_rdata = '0;
        endcase
    end

    assign is_done = (state == STACKER_END);
endmodule
